import * as React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import info from "../data/data.json";
import SEO from "../components/seo";
import Layout from "../components/layout";
import { AuditRequestButton } from "../components/auditRequestModal";

function ArrowIcon() {
  return (
    <svg className="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
      <path d="M5 12h14M13 5l7 7-7 7" />
    </svg>
  );
}

export default function AboutPage() {
  const { t } = useTranslation();
  const { language } = useI18next();

  const servicesHref = language === "fr" ? "/fr/services/" : "/en/services/";

  const backgroundItems = (t("aboutPage.sections.background.items", { returnObjects: true }) as string[]) || [];
  const bullets = (t("about.bullets", { returnObjects: true }) as string[]) || [];
  const asidePills = (t("about.aside.pills", { returnObjects: true }) as string[]) || [];
  const fitItems = (t("aboutPage.sections.fit.items", { returnObjects: true }) as string[]) || [];

  return (
    <Layout data={info}>
      <main>

        {/* ======================================================
            HERO
        ====================================================== */}
        <section className="pf-hero shell">
          <div className="pf-hero-grid">

            <div className="pf-hero-meta">
              <div className="eyebrow">§ 01 · {t("aboutPage.hero.kicker")}</div>
              <div className="mono muted" style={{ marginTop: "12px" }}>
                Montréal (ET) · EN / FR / ES
              </div>
            </div>

            <h1
              className="display-xl pf-title reveal"
              aria-label={t("aboutPage.hero.title") as string}
            >
              {t("aboutPage.hero.title")}
            </h1>

            <p className="body-lg pf-intro reveal">{t("aboutPage.hero.desc")}</p>

            <div className="reveal" style={{ display: "flex", gap: "12px", flexWrap: "wrap", paddingTop: "8px" }}>
              <AuditRequestButton
                serviceName={t("contact.auditService") as string}
                source="about.hero.primary"
                className="btn btn-dark"
              >
                {t("contact.cta")}
                <ArrowIcon />
              </AuditRequestButton>
              <Link to={servicesHref} className="btn btn-ghost">
                {t("selectedProjects.labels.viewAllServices")}
              </Link>
            </div>

          </div>
        </section>

        {/* ======================================================
            WHAT THE WORK IS BUILT AROUND
        ====================================================== */}
        <section className="who shell">
          <header className="sec-head">
            <div className="eyebrow">§ 02 · {t("aboutPage.sections.background.title").split(" ").slice(0, 3).join(" ")}</div>
            <h2 className="display-l reveal">{t("aboutPage.sections.background.title")}</h2>
            <p className="body-lg reveal">{t("aboutPage.sections.background.desc")}</p>
          </header>

          <div className="who-grid" style={{ gridTemplateColumns: "repeat(3, 1fr)" }}>
            {backgroundItems.map((item) => (
              <article key={item} className="who-card tilt reveal">
                <div className="tilt-inner">
                  <p className="body" style={{ fontSize: "14px", lineHeight: 1.65 }}>{item}</p>
                </div>
              </article>
            ))}
          </div>
        </section>

        {/* ======================================================
            HOW I WORK
        ====================================================== */}
        <section className="who shell">
          <header className="sec-head">
            <div className="eyebrow">§ 03 · {t("aboutPage.sections.workflow.title")}</div>
            <h2 className="display-l reveal">{t("aboutPage.sections.workflow.title")}</h2>
            <p className="body-lg reveal">{t("aboutPage.sections.workflow.desc")}</p>
          </header>

          <div className="who-grid" style={{ gridTemplateColumns: "1fr 1fr" }}>
            <article className="who-card tilt reveal">
              <div className="tilt-inner">
                <h3 className="display-s" style={{ fontSize: "clamp(18px, 1.6vw, 24px)", marginBottom: "20px" }}>
                  {t("aboutPage.sections.workflow.title")}
                </h3>
                <p className="body" style={{ fontSize: "14px", marginBottom: "20px" }}>{t("about.p1")}</p>
                <ul style={{ paddingLeft: "1.1em", display: "flex", flexDirection: "column", gap: "8px" }}>
                  {bullets.map((b) => (
                    <li key={b} className="body" style={{ fontSize: "13px" }}>{b}</li>
                  ))}
                </ul>
                <div style={{ marginTop: "28px" }}>
                  <a
                    href={info.linkedIn}
                    target="_blank"
                    rel="noreferrer"
                    className="btn btn-ghost"
                    style={{ display: "inline-flex" }}
                  >
                    {t("about.cta")}
                    <ArrowIcon />
                  </a>
                </div>
              </div>
            </article>

            <div className="reveal" style={{ display: "flex", flexDirection: "column" }}>
              <div className="avail-card" style={{ height: "100%" }}>
                <div className="eyebrow" style={{ marginBottom: "20px" }}>
                  § {t("about.aside.title")}
                </div>
                <p className="body">{t("about.aside.desc")}</p>
                <div style={{ display: "flex", flexWrap: "wrap", gap: "8px", position: "relative", zIndex: 1 }}>
                  {asidePills.map((pill) => (
                    <span
                      key={pill}
                      className="mono"
                      style={{
                        fontSize: "11px",
                        padding: "5px 14px",
                        border: "1px solid rgba(255,255,255,0.2)",
                        borderRadius: "100px",
                        color: "oklch(85% 0.02 70deg)",
                        letterSpacing: "0.08em",
                      }}
                    >
                      {pill}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* ======================================================
            BEST FIT
        ====================================================== */}
        <section className="who shell">
          <header className="sec-head">
            <div className="eyebrow">§ 04 · {t("aboutPage.sections.fit.title")}</div>
            <h2 className="display-l reveal">{t("aboutPage.sections.fit.title")}</h2>
          </header>

          <div className="who-grid" style={{ gridTemplateColumns: "repeat(3, 1fr)" }}>
            {fitItems.map((item, i) => (
              <article key={item} className="who-card tilt reveal">
                <div className="tilt-inner">
                  <div className="proc-num" style={{ marginBottom: "16px" }}>{String(i + 1).padStart(2, "0")}</div>
                  <p className="body" style={{ fontSize: "14px", lineHeight: 1.65 }}>{item}</p>
                </div>
              </article>
            ))}
          </div>
        </section>

        {/* ======================================================
            AVAILABILITY — CTA
        ====================================================== */}
        <section className="portfolio-preview shell">
          <div
            className="portfolio-foot"
            style={{ paddingTop: "80px", borderTop: "1px solid var(--rule)" }}
          >
            <div>
              <p className="eyebrow">§ 05 · {t("aboutPage.sections.availability.title")}</p>
              <p className="body-lg" style={{ marginTop: "12px", maxWidth: "48ch" }}>
                {t("aboutPage.sections.availability.desc")}
              </p>
            </div>
            <div style={{ display: "flex", gap: "12px", flexWrap: "wrap", alignSelf: "flex-start" }}>
              <AuditRequestButton
                serviceName={t("contact.auditService") as string}
                source="about.cta.primary"
                className="btn btn-dark"
              >
                {t("contact.cta")}
                <ArrowIcon />
              </AuditRequestButton>
              <a
                href={info.whatsapp}
                target="_blank"
                rel="noreferrer"
                className="btn btn-ghost"
              >
                {t("contact.secondary")}
              </a>
            </div>
          </div>
        </section>

      </main>
    </Layout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

export const Head: HeadFC = ({ location, pageContext }) => {
  const language = (pageContext as { language?: string }).language || "fr";
  const pathname = language === "fr" ? "/fr/about/" : "/en/about/";
  return (
    <SEO
      data={info}
      titleKey="seo.about.metaTitle"
      descriptionKey="seo.about.metaDescription"
      pathname={pathname}
      currentPathname={location.pathname}
      language={language}
      alternates={[
        { hrefLang: "fr", href: "https://riano.ca/fr/about/" },
        { hrefLang: "en", href: "https://riano.ca/en/about/" },
        { hrefLang: "x-default", href: "https://riano.ca/fr/about/" },
      ]}
      schemaType="ProfessionalService"
    />
  );
};
